// Query compilation is local; every candidate hit and score comes from OpenSearch.
import { METHODS, getMethod, supports, executeSearch, indexForMethod } from './registry.mjs';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { api, INDEX, CORPUS_STORE, hash } from './service.mjs';
let descriptorHashes;
const descriptors=()=>descriptorHashes??=Promise.all(['features.jsonl','refinement-features.jsonl'].map(async name=>[name,hash(await readFile(path.join(CORPUS_STORE,name)))])).then(Object.fromEntries);

export async function createCandidate({ config, context }) {
  const method = getMethod(config.method ?? config.id);
  const index = indexForMethod(method,config.index ?? INDEX);
  return {
    metadata: {
      id: config.id, label: method.label, ...method,
      sourceFiles: ['exploration/adapter.mjs', 'exploration/registry.mjs', 'exploration/methods.mjs', 'exploration/methods-fast.mjs', 'exploration/methods-bounded.mjs', 'exploration/methods-transport.mjs', 'exploration/methods-direct-palette.mjs', 'exploration/methods-palette-bounded.mjs', 'exploration/methods-precision-typed.mjs', 'exploration/methods-rank-features.mjs', 'exploration/rank-features-index.mjs', 'exploration/methods-relative.mjs', 'exploration/refinement-features.mjs', 'exploration/query.mjs', 'exploration/corpus-colors.mjs', 'exploration/service.mjs'],
      execution: { kind: 'opensearch', retrieval: method.approximate ? 'approximate' : 'exact-stored-objective' },
      limitations: [...(method.limitations ?? []), 'Development judgments are from one observer; new ZIP wallpapers are unjudged.'],
    },
    supports(caseData) { return supports(method, caseData.query, caseData); },
    async prepare() {
      const [version, count, documents] = await Promise.all([api(''), api(`${index}/_count`),api(`${index}/_mget?_source=false`,{method:'POST',body:{ids:context.corpus.map(c=>c.id)}})]);
      if (count.body.count < context.corpus.length) throw Error(`Index has ${count.body.count} documents; corpus has ${context.corpus.length}`);
      if(documents.body.docs.some(d=>!d.found))throw Error('Index is missing required corpus assets');
      return { index, count: count.body.count, descriptorHashes:await descriptors(), execution: { kind: 'opensearch', version: version.body.version.number,
        topology: 'single node; one shard; 2 GiB heap; 4 GiB container limit', retrieval: method.approximate ? 'approximate' : 'exact-stored-objective',
        boundary: 'query compilation + HTTP + OpenSearch filtering/ranking + response decoding' } };
    },
    async search({ caseData, limit, signal }) {
      const result = await executeSearch({ index, method, query: caseData.query, limit, eligibleIds: caseData.eligibleIds, excludedIds: caseData.excludedIds, parameters: config.parameters, signal });
      return { ...result, evidence: { ...result.evidence, method: method.id, approximate: method.approximate ?? false } };
    },
  };
}

export { METHODS };

arrival-load.mjs:
// Real OpenSearch arrival-rate benchmark. All filtering/ranking stays in the service.
import { readFile, readdir, mkdir, writeFile, rename } from 'node:fs/promises';
import path from 'node:path';
import { performance } from 'node:perf_hooks';
import { METHODS, supports, executeSearch } from './registry.mjs';
import { BASE, STORE, api, safeIndexName, hash } from './service.mjs';
import { WORKLOAD } from './workload.mjs';
import { runArrivals } from './arrival-scheduler.mjs';

const args = process.argv.slice(2);
const option = (name, fallback) => { const index = args.indexOf(name); return index < 0 ? fallback : args[index + 1]; };
const index = safeIndexName(option('--index', 'color-exploration-scale-features-v1'));
const seedIndex = safeIndexName(option('--seed-index', 'color-exploration-scale-vectors-v1'));
const selected = option('--methods', 'native-area-linear').split(',');
const rates = option('--rates', '50,200').split(',').map(Number);
const durationMs = Number(option('--seconds', '15')) * 1000;
const maxInFlight = Number(option('--max-inflight', '128'));
const queryIds = option('--query-ids')?.split(',');

async function resources() {
  const response = await api('_nodes/stats/process,jvm,indices?filter_path=nodes.*.process.cpu.total_in_millis,nodes.*.jvm.mem.heap_used_in_bytes,nodes.*.indices.search,nodes.*.indices.store.size_in_bytes');
  return { at: new Date().toISOString(), node: Object.values(response.body.nodes)[0],
    clientCpu: process.cpuUsage(), clientMemory: process.memoryUsage() };
}

async function main() {
  if (!BASE.includes(':19217')) throw new Error('Arrival load must use isolated OpenSearch port 19217');
  const methods = selected.map(id => {
    const method = METHODS.find(item => item.id === id);
    if (!method) throw new Error('Unknown method: ' + id);
    return method;
  });
  if (!rates.length || rates.some(rate => !Number.isFinite(rate) || rate <= 0 || rate > 5000)
    || !(durationMs > 0 && durationMs <= 300000) || !Number.isInteger(maxInFlight) || maxInFlight < 1) {
    throw new Error('Invalid arrival-rate benchmark configuration');
  }
  const directory = path.join(STORE, 'arrival-load', new Date().toISOString().replaceAll(':', '-'));
  await mkdir(directory, { recursive: true });
  const sourceNames = (await readdir(new URL('.', import.meta.url))).filter(name => name.endsWith('.mjs')).sort();
  const sourceSnapshot = Object.fromEntries(await Promise.all(sourceNames.map(async name => [name, await readFile(new URL(name, import.meta.url), 'utf8')])));
  await writeFile(path.join(directory, 'source-snapshot.json'), JSON.stringify(sourceSnapshot, null, 2));
  const count = (await api(index + '/_count')).body.count;
  const result = { schemaVersion: 1, startedAt: new Date().toISOString(), base: BASE, index, count,
    version: (await api('')).body.version,
    configuration: { methods: selected, rates, durationMs, maxInFlight, seedIndex, queryIds },
    sourceSnapshotHash: hash(sourceSnapshot), sourceSnapshot: path.join(directory, 'source-snapshot.json'),
    topology: { nodes: 1, shardsPerIndex: 1, replicas: 0, cpuLimit: 8, javaHeapGiB: 4, containerMemoryGiB: 12 },
    corpus: 'Synthetic mixtures of 545 source descriptors; no additional relevance labels.',
    latencyBoundary: 'Scheduled arrival to complete decoded service result, including client dispatch delay; failures and client rejections count.',
    limitations: ['Single shared host and client, one OpenSearch node; not a production capacity guarantee.',
      'Deterministic evenly spaced arrivals with a rotating mixed workload, not realistic bursty traffic.',
      'CPU counters are cached; resource samples are observations, not instantaneous peaks.',
      'Client in-flight cap rejects excess arrivals explicitly; these are failed requests.'],
    profiles: [] };
  const save = async () => {
    await writeFile(path.join(directory, 'load.partial.json'), JSON.stringify(result, null, 2));
    await rename(path.join(directory, 'load.partial.json'), path.join(directory, 'load.json'));
  };
  console.log('ARRIVAL_ARTIFACT ' + path.join(directory, 'load.json'));
  for (const method of methods) {
    const workload = WORKLOAD.filter(item => (!queryIds || queryIds.includes(item.id)) && supports(method, item.query).supported);
    if (!workload.length) throw new Error('No supported workload queries for ' + method.id);
    const request = async item => {
      const response = await executeSearch({ index, seedIndex, method, query: item.query,
        filter: item.filter, limit: 20, timeoutMs: 2000, serviceTimeout: '950ms' });
      return { queryId: item.id, serviceTookMs: response.evidence.serviceTookMs,
        hitCount: response.hits.length, topHit: response.hits[0] };
    };
    const warmups = [];
    for (const item of workload) {
      const started = performance.now();
      try { warmups.push({ ...await request(item), elapsedMs: performance.now() - started }); }
      catch (error) { warmups.push({ queryId: item.id, error: error.message, elapsedMs: performance.now() - started }); }
    }
    for (const rate of rates) {
      const before = await resources(), samples = [];
      let sampling = false, stopped = false;
      const timer = setInterval(async () => {
        if (sampling || stopped) return;
        sampling = true;
        try { samples.push(await resources()); }
        catch (error) { samples.push({ error: error.message }); }
        finally { sampling = false; }
      }, 1000);
      let measurement;
      try {
        measurement = await runArrivals({ rate, durationMs, maxInFlight,
          run: async ordinal => {
            const item = workload[ordinal % workload.length];
            try { return await request(item); }
            catch (error) { return { queryId: item.id, error: error.message }; }
          } });
      } finally { stopped = true; clearInterval(timer); }
      while (sampling) await new Promise(resolve => setTimeout(resolve, 5));
      const after = await resources();
      const warmupErrors = warmups.filter(item => item.error).length;
      const warmupOverOneSecond = warmups.filter(item => item.elapsedMs >= 1000).length;
      const profile = { method: method.id, index, count, ...measurement, workload, warmups,
        warmupErrors, warmupOverOneSecond,
        strictViable: measurement.viableAtTestedLoad && warmupErrors === 0 && warmupOverOneSecond === 0,
        cpuMs: after.node.process.cpu.total_in_millis - before.node.process.cpu.total_in_millis,
        serviceCpuMs: (after.clientCpu.user + after.clientCpu.system - before.clientCpu.user - before.clientCpu.system) / 1000,
        peakObservedHeapBytes: Math.max(...[before, ...samples, after].map(item => item.node?.jvm?.mem?.heap_used_in_bytes ?? 0)),
        peakObservedServiceRssBytes: Math.max(...[before, ...samples, after].map(item => item.clientMemory?.rss ?? 0)),
        before, after, samples };
      result.profiles.push(profile);
      await save();
      console.log(JSON.stringify({ ...profile, workload: undefined, warmups: undefined, trials: undefined, before: undefined, after: undefined, samples: undefined }));
      if (!measurement.viableAtTestedLoad) break;
    }
  }
  result.finishedAt = new Date().toISOString();
  await save();
}

await main();

arrival-scheduler.mjs:
// Arrival-rate load: scheduled arrivals continue when earlier requests are slow.
// A bounded client rejects excess work explicitly instead of hiding its queue delay.
import { performance } from 'node:perf_hooks';

export const percentile = (values, fraction) => {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.max(0, Math.ceil(sorted.length * fraction) - 1)];
};

export function summarizeArrivals(records) {
  const latencies = records.map(record => record.elapsedMs);
  const errors = records.filter(record => record.error).length;
  const overOneSecond = records.filter(record => record.elapsedMs >= 1000).length;
  return {
    requests: records.length,
    errors,
    clientRejected: records.filter(record => record.clientRejected).length,
    overOneSecond,
    p50Ms: percentile(latencies, 0.5),
    p95Ms: percentile(latencies, 0.95),
    p99Ms: percentile(latencies, 0.99),
    maxMs: percentile(latencies, 1),
    maximumSchedulerDelayMs: percentile(records.map(record => record.schedulerDelayMs), 1),
    viableAtTestedLoad: records.length > 0 && errors === 0 && overOneSecond === 0,
  };
}

export async function runArrivals({ rate, durationMs, maxInFlight = 256, run,
  now = () => performance.now(), sleep = milliseconds => new Promise(resolve => setTimeout(resolve, milliseconds)) }) {
  if (!(rate > 0) || !Number.isFinite(rate) || !(durationMs > 0) || !Number.isFinite(durationMs)
    || !Number.isInteger(maxInFlight) || maxInFlight < 1 || typeof run !== 'function') {
    throw new Error('Positive rate/duration, positive integer client limit and a request function are required');
  }
  const total = Math.floor(rate * durationMs / 1000);
  if (!total || total > 1_000_000) throw new Error('Arrival count must be 1..1000000');
  const started = now(), records = [], pending = new Set();
  let peakInFlight = 0;
  for (let ordinal = 0; ordinal < total; ordinal++) {
    const scheduled = started + ordinal * 1000 / rate;
    const remaining = scheduled - now();
    if (remaining > 0) await sleep(remaining);
    const dispatched = now();
    const schedulerDelayMs = Math.max(0, dispatched - scheduled);
    if (pending.size >= maxInFlight) {
      records[ordinal] = { ordinal, schedulerDelayMs, elapsedMs: schedulerDelayMs,
        error: 'Client in-flight limit reached', clientRejected: true };
      continue;
    }
    const request = Promise.resolve().then(() => run(ordinal)).then(
      result => ({ ...result }),
      error => ({ error: error.message ?? String(error) }),
    ).then(result => {
      records[ordinal] = { ...result, ordinal, schedulerDelayMs,
        requestMs: now() - dispatched, elapsedMs: now() - scheduled };
    }).finally(() => pending.delete(request));
    pending.add(request);
    peakInFlight = Math.max(peakInFlight, pending.size);
  }
  await Promise.all(pending);
  return { ...summarizeArrivals(records), rate, durationMs, elapsedMs: now() - started,
    maxInFlight, peakInFlight, trials: records };
}

arrival-scheduler.test.mjs:
import test from 'node:test';
import assert from 'node:assert/strict';
import { runArrivals, summarizeArrivals } from './arrival-scheduler.mjs';

test('arrival metrics count failed and slow requests instead of only successful latency', () => {
  const result = summarizeArrivals([
    { elapsedMs: 5, schedulerDelayMs: 0 },
    { elapsedMs: 1200, schedulerDelayMs: 100, error: 'timeout' },
  ]);
  assert.equal(result.p95Ms, 1200);
  assert.equal(result.errors, 1);
  assert.equal(result.overOneSecond, 1);
  assert.equal(result.viableAtTestedLoad, false);
});

test('arrivals retain their schedule while a prior request remains pending', async () => {
  let clock = 0, release;
  const gate = new Promise(resolve => { release = resolve; });
  const result = await runArrivals({ rate: 1000, durationMs: 4, maxInFlight: 1,
    now: () => clock,
    sleep: async amount => { clock += amount; if (clock >= 3) setTimeout(release, 0); },
    run: async () => { await gate; clock += 8; return { queryId: 'slow' }; },
  });
  assert.equal(result.requests, 4);
  assert.equal(result.clientRejected, 3);
  assert.equal(result.peakInFlight, 1);
  assert.equal(result.trials[0].requestMs, 11);
  assert.equal(result.viableAtTestedLoad, false);
});

test('arrival scheduler records request exceptions and rejects invalid configuration', async () => {
  const result = await runArrivals({ rate: 1, durationMs: 1000,
    run: async () => { throw new Error('service failed'); } });
  assert.equal(result.errors, 1);
  assert.match(result.trials[0].error, /service failed/);
  await assert.rejects(runArrivals({ rate: 0, durationMs: 1, run() {} }));
});

