import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { startBrowserServer } from './browser.mjs';

const moduleUrl = process.env.COLOR_EXPLORATION_PROVIDER
  ? pathToFileURL(resolve(process.env.COLOR_EXPLORATION_PROVIDER))
  : new URL('./browser-provider.mjs', import.meta.url);
const { createBrowserProvider } = await import(moduleUrl.href);
const provider = await createBrowserProvider();
const server = await startBrowserServer({
  ...provider,
  host: process.env.COLOR_EXPLORATION_HOST ?? '0.0.0.0',
  port: Number(process.env.COLOR_EXPLORATION_PORT ?? 8225),
});
console.log(`Color query lab listening on http://0.0.0.0:${server.address().port}; ${provider.methods.length} methods, ${provider.corpus.length} assets.`);
for (const signal of ['SIGTERM', 'SIGINT']) process.on(signal, () => {
  server.close(async () => { await provider.close?.(); process.exit(0); });
  server.closeIdleConnections();
});

browser-provider.mjs:
import { METHODS, getMethod, supports, executeSearch } from './registry.mjs';
import { loadExpandedCorpus, searchIndex, INDEX } from './service.mjs';
import { renderFindings } from './summary.mjs';

export async function createBrowserProvider() {
  const corpus=await loadExpandedCorpus();
  const fixtureIds=corpus.filter(c=>c.filename.endsWith('.svg')).map(c=>c.id);
  return {
    methods: METHODS,
    corpus,
    description: 'Throwaway color-query experiments. Every returned wallpaper and score comes from real OpenSearch. All original wallpapers and the complete supplied ZIP are indexed.',
    reportUrl: 'http://zerotwo:8224/latest',
    findingsUrl: '/findings',
    getFindingsHtml: async()=> (await renderFindings()).html,
    async search({ methodId, query, limit, signal, includeFixtures=false }) {
      const method = getMethod(methodId);
      const support = supports(method, query, {});
      if (!support.supported) return { supported: false, reason: support.reason ?? 'Unsupported query', hits: [], warnings: support.warnings };
      const result = await executeSearch({ index:INDEX,method,query,limit,signal,excludedIds:includeFixtures?undefined:fixtureIds });
      return { ...result, evidence: { ...result.evidence, warnings: support.warnings, approximate: method.approximate ?? false } };
    },
  };
}

