// Exact safe pruning: service scores the seed and service ranks the global final query.
// The application only turns the kth service score into necessary numeric bounds.
import { buildQuery, interpretQuery } from './methods.mjs';
import { searchIndex } from './service.mjs';

export const BOUNDED_METHOD = Object.freeze({
  id: 'feature-composition-bounded', label: 'Named composition with exact indexed bounds',
  family: 'composition-bounded', representation: 'named-features', approximate: false,
  scoring: 'composition', scalar: true, searchKind: 'bounded',
  limitations: [
    'Three service searches: cheap indexed seed, exact service seed score, globally bounded exact final score.',
    'No fixed candidate cap; weak bounds can still scan all metadata-matching documents.',
    'Shares the marginal-area union approximation of the feature composition reference.',
    'The multi-query exactness guarantee assumes a stable index; production needs a consistent snapshot/PIT or an equivalent versioned search view.',
  ],
});

/** Necessary per-feature bounds for scores >= threshold. Bounds deliberately round outwards. */
export function safeBounds(compiled, threshold, parameters = {}) {
  if (!Number.isFinite(threshold) || threshold <= 0) return [];
  const lowerScore = Math.max(0, threshold - 2e-6);
  if (!lowerScore) return [];
  const areaPower = parameters.areaPower ?? 0.65;
  const qualityPenalty = parameters.qualityPenalty ?? 0.35;
  const outsidePenalty = parameters.outsidePenalty ?? 6;
  const excessPenalty = parameters.excessPenalty ?? 1;
  if (!(areaPower > 0) || qualityPenalty < 0 || outsidePenalty < 0 || excessPenalty < 1) throw new Error('Exact bounds require positive areaPower, nonnegative penalties, and excessPenalty >= 1.');
  if (compiled.special) return []; // The normal search already uses the exact script for these intents.
  const n = compiled.targets.length;
  if (compiled.mode === 'vibe') {
    // mean(a_i^p * q_i) <= (a_j^p + n - 1)/n because every q_i <= 1.
    const required = Math.pow(Math.max(0, lowerScore * n - (n - 1)), 1 / areaPower);
    return compiled.targets.map(t => ({ range: { [`cov_${t.name}`]: { gte: Math.max(0, Math.floor(required * 10000) - 2) } } }));
  }
  // S=1/(1+E), E >= mean(abs(a_i-t_i)); therefore abs(a_i-t_i) <= n*(1/S-1).
  const maximumDeviation = n * Math.max(0, 1 / lowerScore - 1);
  return compiled.targets.map(t => ({ range: { [`cov_${t.name}`]: {
    gte: Math.max(0, Math.floor((t.amount - maximumDeviation) * 10000) - 2),
    lte: Math.min(10000, Math.ceil((t.amount + maximumDeviation) * 10000) + 2),
  } } }));
}

export async function searchBounded({ index, query, limit = 20, eligibleIds, excludedIds, filter, parameters = {}, signal, search = searchIndex }) {
  const compiled = interpretQuery(query);
  if (!compiled.supported) throw new Error(compiled.reason);
  const exact = { method: 'feature-composition-exact', query, limit, eligibleIds, excludedIds, filter, parameters };
  if (compiled.special) {
    const result = await search(index, buildQuery(exact), { signal });
    return { ...result, evidence: { ...result.evidence, strategy: 'exact-script-compound-intent', finalGloballyEligible: true, serviceSearches: 1 } };
  }
  const seedLimit = Math.min(10000, Math.max(limit, parameters.seedLimit ?? limit * 4));
  const seed = await search(index, buildQuery({ ...exact, method: 'native-area-linear', limit: seedLimit }), { signal });
  if (!seed.hits.length) return { ...seed, evidence: { ...seed.evidence, strategy: 'empty-indexed-seed', finalGloballyEligible: true, serviceSearches: 1 } };
  const seedFilter = [...(filter ? Array.isArray(filter) ? filter : [filter] : []), { ids: { values: seed.hits.map(hit => hit.id) } }];
  const scoredSeed = await search(index, buildQuery({ ...exact, filter: seedFilter }), { signal });
  if (seed.hits.length < seedLimit) {
    // Native seed returned fewer than its requested size, so it included every eligible document.
    return { ...scoredSeed, evidence: { ...scoredSeed.evidence, strategy: 'seed-covered-full-eligible-set', seedCount: seed.hits.length, finalGloballyEligible: true, serviceSearches: 2 } };
  }
  const threshold = scoredSeed.hits.at(-1)?.score ?? 0;
  const bounds = safeBounds(compiled, threshold, parameters);
  const finalFilter = [...(filter ? Array.isArray(filter) ? filter : [filter] : []), ...bounds];
  const result = await search(index, buildQuery({ ...exact, filter: finalFilter }), { signal });
  return { ...result, evidence: { ...result.evidence, strategy: 'exact-global-numeric-bounds', serviceSearches: 3,
    seedCount: seed.hits.length, threshold, bounds, seedServiceTookMs: seed.evidence?.serviceTookMs,
    scoreSeedServiceTookMs: scoredSeed.evidence?.serviceTookMs, finalGloballyEligible: true,
    guarantee: 'Any document capable of tying or beating the kth seed score passes necessary bounds; the final OpenSearch query searches that entire global set.' } };
}

methods-bounded.test.mjs:
import test from 'node:test';
import assert from 'node:assert/strict';
import { safeBounds, searchBounded } from './methods-bounded.mjs';
import { interpretQuery, buildQuery } from './methods.mjs';
import { INDEX, searchIndex } from './service.mjs';

test('proportion bound retains every possible winner including float-boundary ties', () => {
  const compiled = interpretQuery({ colorTargets: [{ colorName: 'green', targetImagePercent: 40 }, { colorName: 'red', targetImagePercent: 40 }] });
  const score = 1 / 1.08;
  const bounds = safeBounds(compiled, score).map(b => Object.values(b.range)[0]);
  for (let green = 0; green <= 10000; green += 50) for (let red = 0; red <= 10000; red += 50) {
    const optimistic = 1 / (1 + (Math.abs(green / 10000 - 0.4) + Math.abs(red / 10000 - 0.4)) / 2);
    if (optimistic >= score - 1e-7) {
      assert.ok(green >= bounds[0].gte && green <= bounds[0].lte);
      assert.ok(red >= bounds[1].gte && red <= bounds[1].lte);
    }
  }
});

test('bounded final search does not cap eligibility to seed document ids', async () => {
  const calls = [];
  const search = async (_index, body) => {
    calls.push(body);
    if (calls.length === 1) return { hits: [{ id: 'seed', score: 0.9 }] };
    if (calls.length === 2) return { hits: [{ id: 'seed', score: 0.8 }] };
    return { hits: [{ id: 'previously-unseen-global-winner', score: 0.95 }] };
  };
  const result = await searchBounded({ index: 'ignored', query: { text: 'red' }, limit: 1, parameters: { seedLimit: 1 }, search });
  assert.equal(result.hits[0].id, 'previously-unseen-global-winner');
  assert.equal(calls.length, 3);
  assert.doesNotMatch(JSON.stringify(calls[2]), /"seed"/);
  assert.match(JSON.stringify(calls[2]), /cov_red/);
});

test('real bounded service ordering equals complete reference top results', { skip: process.env.COLOR_EXPLORATION_METHOD_INTEGRATION !== '1' }, async () => {
  for (const query of [{ text: 'red' }, { text: 'dark' }, { colorTargets: [{ colorName: 'green', targetImagePercent: 40 }] }, { colorTargets: [{ colorName: 'grayscale', targetImagePercent: 80 }, { colorName: 'red', targetImagePercent: 20 }] }]) {
    const reference = await searchIndex(INDEX, buildQuery({ method: 'feature-composition-exact', query, limit: 20 }));
    const actual = await searchBounded({ index: INDEX, query, limit: 20, parameters: { seedLimit: 20 } });
    assert.deepEqual(actual.hits, reference.hits);
    assert.equal(actual.evidence.finalGloballyEligible, true);
  }
});

methods-direct-palette.mjs:
// Direct palette colors: no RGB4096 lookup or additional range-boundary quantization.
import { interpretQuery, metadataFilter } from './query.mjs';

export const DIRECT_PALETTE_METHODS = Object.freeze([
  { id: 'palette-direct-balanced', label: 'Direct Palette32 balanced area and color', family: 'direct-palette', representation: 'palette32-direct', approximate: false, searchKind: 'direct-palette',
    limitations: ['Original 24-bit palette centroids are evaluated directly in Painless; the 32-color palette remains a lossy image representation.', 'Named regions and scoring weights are provisional; overlapping portions use marginal area.', 'Purity penalties apply only to complete palettes; partial queries use target error.'] },
  { id: 'palette-direct-precision', label: 'Direct Palette32 with shade-first picked colors', family: 'direct-palette', representation: 'palette32-direct', approximate: false, searchKind: 'direct-palette', shadeFirst: true,
    limitations: ['Picked-color vibe requests prioritize conditional shade quality after 5% matching area.', 'The 5% support threshold is an explicit experimental heuristic; no model is trained.', 'Palette reduction still loses within-cluster colors, though range checks no longer snap centroids to coarse bins.'] },
]);

export const DIRECT_MEMBERSHIP = `
  double r = ((rgb >> 16) & 255) / 255.0;
  double g = ((rgb >> 8) & 255) / 255.0;
  double b = (rgb & 255) / 255.0;
  double rr = r <= 0.04045 ? r / 12.92 : Math.pow((r + 0.055) / 1.055, 2.4);
  double gg = g <= 0.04045 ? g / 12.92 : Math.pow((g + 0.055) / 1.055, 2.4);
  double bb = b <= 0.04045 ? b / 12.92 : Math.pow((b + 0.055) / 1.055, 2.4);
  double ll = Math.cbrt(0.4122214708 * rr + 0.5363325363 * gg + 0.0514459929 * bb);
  double mm = Math.cbrt(0.2119034982 * rr + 0.6806995451 * gg + 0.1073969566 * bb);
  double ss = Math.cbrt(0.0883024619 * rr + 0.2817188376 * gg + 0.6299787005 * bb);
  double labL = 0.2104542553 * ll + 0.793617785 * mm - 0.0040720468 * ss;
  double labA = 1.9779984951 * ll - 2.428592205 * mm + 0.4505937099 * ss;
  double labB = 0.0259040371 * ll + 0.7827717662 * mm - 0.808675766 * ss;
  double chroma = Math.sqrt(labA * labA + labB * labB);
  double high = Math.max(r, Math.max(g, b));
  double low = Math.min(r, Math.min(g, b));
  double delta = high - low;
  double hsvS = high == 0 ? 0 : delta / high;
  double hslL = (high + low) / 2.0;
  double hslS = delta < 1e-8 ? 0 : delta / (1.0 - Math.abs(2.0 * hslL - 1.0));
  double hue = 0.0;
  if (delta > 0) {
    hue = high == r ? (g - b) / delta : high == g ? (b - r) / delta + 2 : (r - g) / delta + 4;
    hue = ((hue * 60.0) % 360.0 + 360.0) % 360.0;
  }
  double inUnion = 0.0;
  for (int j = 0; j < count; j++) {
    Map target = params.targets[j];
    String name = target.name;
    List ranges = target.ranges;
    boolean inside = false;
    double quality = 0.0;
    if (ranges.size() > 0) {
      double distance = 0.0;
      for (int ri = 0; ri < ranges.size(); ri++) {
        Map range = ranges[ri];
        int space = range.space;
        if (space == 0) {
          double dl = labL - target.lab[0]; double da = labA - target.lab[1]; double db = labB - target.lab[2];
          double d = Math.sqrt(dl * dl + da * da + db * db);
          double radius = range.widths[0];
          distance = Math.max(distance, radius > 0 ? d / radius : d < 1e-8 ? 0.0 : 1e30);
        } else {
          for (int channel = 0; channel < 3; channel++) {
            double d;
            if (space == 1) {
              double value = channel == 0 ? r : channel == 1 ? g : b;
              d = Math.abs(value - target.rgb[channel]);
            } else if (channel == 0) {
              if (range.widths[0] == 1) continue;
              if (delta < 1e-8) d = 1.0;
              else { d = Math.abs(hue / 360.0 - target.hue); d = Math.min(d, 1.0 - d) * 2.0; }
            } else {
              double value = space == 2 ? (channel == 1 ? hsvS : high) : (channel == 1 ? hslS : hslL);
              double anchor = space == 2 ? target.hsv[channel - 1] : target.hsl[channel - 1];
              d = Math.abs(value - anchor);
            }
            double width = range.widths[channel];
            distance = Math.max(distance, width > 0 ? d / width : d < 1e-8 ? 0.0 : 1e30);
          }
        }
      }
      inside = distance <= 1.0 + 1e-9;
      quality = inside ? 1.0 - (1.0 - target.edgeWeight) * Math.min(1.0, distance) : 0.0;
    } else {
      double core = 0.0;
      if (target.hueWidth > 0) {
        double hueDistance = Math.abs(((hue - target.hueCenter + 540.0) % 360.0) - 180.0);
        inside = hueDistance <= target.hueWidth && hsvS >= 0.18 && high >= 0.09 && chroma >= 0.018;
        if (name == 'pink') inside = inside && labL >= 0.56;
        if (name == 'brown') inside = inside && labL >= 0.22 && labL <= 0.65;
        double palePenalty = name == 'red' ? 1.0 - Math.max(0.0, Math.min(1.0, (labL - 0.72) / 0.24)) * 0.65 : 1.0;
        core = (1.0 - hueDistance / target.hueWidth) * Math.sqrt(hsvS) * Math.sqrt(high) * palePenalty;
      } else if (name == 'strict_grayscale') { inside = chroma <= 0.005; core = 1.0 - chroma / 0.005; }
      else if (name == 'grayscale') { inside = chroma <= 0.035; core = 1.0 - chroma / 0.035; }
      else if (name == 'near_neutral') { inside = chroma <= 0.065; core = 1.0 - chroma / 0.065; }
      else if (name == 'black') { inside = labL <= 0.25; core = 1.0 - labL / 0.25; }
      else if (name == 'gray') { inside = chroma <= 0.045 && labL >= 0.2 && labL <= 0.88; core = (1.0 - chroma / 0.045) * (1.0 - Math.abs(labL - 0.54) / 0.34); }
      else if (name == 'white') { inside = chroma <= 0.055 && labL >= 0.86; core = (1.0 - chroma / 0.055) * (labL - 0.86) / 0.14; }
      else if (name == 'dark') { inside = labL <= 0.5; core = 1.0 - labL / 0.5; }
      else if (name == 'light') { inside = labL >= 0.72; core = (labL - 0.72) / 0.28; }
      else if (name == 'bright') { inside = high >= 0.72 && labL >= 0.55; core = (high - 0.72) / 0.28; }
      else if (name == 'vivid') { inside = hsvS >= 0.55 && high >= 0.5; core = (hsvS - 0.55) / 0.45 * (high - 0.5) / 0.5; }
      else if (name == 'muted') { inside = hsvS <= 0.4 && chroma <= 0.085; core = 1.0 - chroma / 0.085; }
      quality = inside ? 0.5 + 0.5 * Math.max(0.0, Math.min(1.0, core)) : 0.0;
    }
    if (inside) { areas[j] += mass; masses[j] += mass * quality; inUnion = 1.0; }
  }
  union += mass * inUnion;
`;

export const DIRECT_PALETTE_SCRIPT = `
int count = params.targets.size();
double[] areas = new double[count]; double[] masses = new double[count];
double union = 0.0;
double total = doc['palette_total'].value;
for (int i = 0; i < doc['palette32_packed'].size(); i++) {
  long packed = doc['palette32_packed'].get(i);
  long rgb = packed / 65536L;
  double mass = (packed % 65536L) / total;
  ${DIRECT_MEMBERSHIP}
}
if (params.diagnostic == 'area') return areas[0];
if (params.diagnostic == 'quality') return areas[0] > 0 ? masses[0] / areas[0] : 0.0;
if (params.special == 'gray_red_accents') {
  double red = areas[1]; double quality = red > 0 ? masses[1] / red : 0.0;
  double accent = Math.min(1.0, red / 0.12) * Math.max(0.0, 1.0 - Math.max(0.0, red - 0.35) / 0.65);
  return Math.max(0.0, areas[0] * accent * (0.4 + 0.6 * quality) - params.outsidePenalty * Math.max(0.0, 1.0 - union));
}
if (params.special == 'dark_bright_accents') {
  double accent = Math.min(1.0, areas[1] / 0.03) * Math.max(0.0, 1.0 - Math.max(0.0, areas[1] - 0.15) / 0.85);
  return areas[0] * accent;
}
if (params.mode == 'vibe') {
  double score = 0.0;
  for (int j = 0; j < count; j++) {
    double quality = areas[j] > 0 ? masses[j] / areas[j] : 0.0;
    double support = params.shadeFirst && params.targets[j].name == '' ? Math.min(1.0, areas[j] / params.minimumSupport) : Math.pow(areas[j], params.areaPower);
    score += support * quality;
  }
  return score / count;
}
double error = 0.0; double qualityError = 0.0;
for (int j = 0; j < count; j++) {
  double delta = areas[j] - params.targets[j].amount;
  error += Math.abs(delta) * (delta > 0 ? params.excessPenalty : 1.0);
  double quality = areas[j] > 0 ? masses[j] / areas[j] : 0.0;
  qualityError += Math.min(areas[j], params.targets[j].amount) * (1.0 - quality);
}
error = error / count + params.qualityPenalty * qualityError;
if (params.remainder < 1e-9) error += params.outsidePenalty * Math.max(0.0, 1.0 - union);
return 1.0 / (1.0 + error);
`;

const HUES = { red: [4, 46], orange: [29, 25], yellow: [58, 24], green: [127, 61], teal: [172, 29], cyan: [191, 32], blue: [234, 47], purple: [282, 38], pink: [334, 44], brown: [29, 28] };
function targetParameters(target) {
  const rgb = target.rgb ?? [0, 0, 0];
  const [r, g, b] = rgb, high = Math.max(...rgb), low = Math.min(...rgb), delta = high - low;
  const hue = delta < 1e-8 ? null : (((high === r ? (g - b) / delta : high === g ? (b - r) / delta + 2 : (r - g) / delta + 4) / 6) % 1 + 1) % 1;
  const lightness = (high + low) / 2;
  const ranges = target.ranges.map(range => {
    if (['hsl', 'hsv'].includes(range.space) && range.h < 1 && hue == null) throw new Error('Achromatic anchors require hue distance 100%.');
    const keys = { oklab: ['distance'], rgb: ['r', 'g', 'b'], hsv: ['h', 's', 'v'], hsl: ['h', 's', 'l'] }[range.space];
    return { space: ['oklab', 'rgb', 'hsv', 'hsl'].indexOf(range.space), widths: keys.map(k => range[k]) };
  });
  return { name: target.name ?? '', amount: target.amount, rgb, lab: target.lab ?? [0, 0, 0], hue: hue ?? 0,
    hsv: [high ? delta / high : 0, high], hsl: [delta < 1e-8 ? 0 : delta / (1 - Math.abs(2 * lightness - 1)), lightness],
    ranges, edgeWeight: target.edgeWeight, hueCenter: HUES[target.name]?.[0] ?? 0, hueWidth: HUES[target.name]?.[1] ?? 0 };
}

export function supportsDirectPalette(query) {
  const compiled = interpretQuery(query);
  if (!compiled.supported) return compiled;
  if (compiled.targets.some(t => ['monochromatic', 'rainbow'].includes(t.name))) return { supported: false, reason: 'Direct palette region matching has no global hue-diversity objective.' };
  try { compiled.targets.map(targetParameters); } catch (error) { return { supported: false, reason: error.message }; }
  return { supported: true, compiled, warnings: ['Palette32 is a lossy summary, but membership uses original centroid RGB directly.'] };
}

export function buildDirectPaletteQuery({ method = 'palette-direct-balanced', query, limit = 20, eligibleIds, excludedIds, filter, parameters = {} }) {
  const id = typeof method === 'string' ? method : method.id;
  const definition = DIRECT_PALETTE_METHODS.find(m => m.id === id);
  if (!definition) throw new Error(`Unknown direct palette method: ${id}`);
  const check = supportsDirectPalette(query);
  if (!check.supported) throw new Error(check.reason);
  const compiled = check.compiled;
  const params = { targets: compiled.targets.map(targetParameters), mode: compiled.mode, special: compiled.special ?? '', remainder: compiled.remainder,
    shadeFirst: definition.shadeFirst ?? false, minimumSupport: parameters.minimumSupport ?? 0.05, areaPower: parameters.areaPower ?? 0.65,
    qualityPenalty: parameters.qualityPenalty ?? 0.15, outsidePenalty: parameters.outsidePenalty ?? 6, excessPenalty: parameters.excessPenalty ?? 1.3, diagnostic: '' };
  if (!(params.minimumSupport > 0 && params.minimumSupport <= 1) || !(params.areaPower > 0) || [params.qualityPenalty, params.outsidePenalty, params.excessPenalty].some(v => !Number.isFinite(v) || v < 0)) throw new Error('Invalid direct-palette scoring parameters.');
  return { size: limit, _source: false, track_total_hits: false, sort: [{ _score: 'desc' }, { id: 'asc' }], query: { script_score: {
    query: metadataFilter({ eligibleIds, excludedIds, filter, compiled }), script: { lang: 'painless', source: DIRECT_PALETTE_SCRIPT, params },
  } } };
}

methods-direct-palette.test.mjs:
import test from 'node:test';
import assert from 'node:assert/strict';
import { buildDirectPaletteQuery, supportsDirectPalette } from './methods-direct-palette.mjs';
import { FEATURE_NAMES } from './corpus-colors.mjs';
import { interpretQuery, membership } from './query.mjs';
import { INDEX, searchIndex, loadFeatures } from './service.mjs';

test('direct palette retains RGB24 comparisons and rejects undefined hue ranges', () => {
  const body = buildDirectPaletteQuery({ query: { swatchHex: '#ff2200' }, method: 'palette-direct-precision' });
  assert.equal(body.query.script_score.script.params.shadeFirst, true);
  assert.equal(body.query.script_score.script.params.minimumSupport, 0.05);
  assert.equal(body.query.script_score.script.params.targets[0].ranges[0].space, 0);
  assert.doesNotMatch(body.query.script_score.script.source, /params\.weights/);
  assert.equal(supportsDirectPalette({ mode: 'vibe', targets: [{ color: '#000000', space: 'hsl', tolerance: { h: 0.1, s: 0.02, l: 0.1 } }] }).supported, false);
});

test('direct service membership and quality match independent JS for every pixel family and range space', { skip: process.env.COLOR_EXPLORATION_DIRECT_TEST !== '1' }, async () => {
  const features = (await loadFeatures()).slice(0, 12);
  const queries = FEATURE_NAMES.filter(n => !['monochromatic', 'rainbow'].includes(n)).map(name => ({ mode: 'vibe', targets: [{ name }] }));
  queries.push(...[
    { color: '#ef2020', space: 'oklab', tolerance: { distance: 0.2 } },
    { color: '#4c8c72', space: 'rgb', tolerance: { r: 0.2, g: 0.2, b: 0.2 } },
    { color: '#209040', space: 'hsv', tolerance: { h: 0.3, s: 0.5, v: 0.4 } },
    { color: '#000000', space: 'hsl', tolerance: { h: 1, s: 0.02, l: 0.4 } },
  ].map(t => ({ mode: 'vibe', targets: [t] })));
  for (const query of queries) {
    const target = interpretQuery(query).targets[0];
    for (const diagnostic of ['area', 'quality']) {
      const body = buildDirectPaletteQuery({ query, eligibleIds: features.map(f => f.id), limit: 20 });
      body.query.script_score.script.params.diagnostic = diagnostic;
      const result = await searchIndex(INDEX, body);
      assert.equal(result.hits.length, features.length);
      const values = new Map(result.hits.map(h => [h.id, h.score]));
      for (const feature of features) {
        let area = 0, qualityMass = 0;
        for (const packed of feature.palette32_packed) {
          const rgb24 = Math.floor(packed / 65536);
          const rgb = [(rgb24 >> 16) & 255, (rgb24 >> 8) & 255, rgb24 & 255].map(v => v / 255);
          const mass = packed % 65536 / feature.palette_total;
          const actual = membership(rgb, target);
          area += mass * actual.area; qualityMass += mass * actual.area * actual.quality;
        }
        const expected = diagnostic === 'area' ? area : area > 0 ? qualityMass / area : 0;
        assert.ok(Math.abs(values.get(feature.id) - expected) < 2e-6, `${feature.id}, ${target.name ?? target.color}, ${diagnostic}: ${values.get(feature.id)} != ${expected}`);
      }
    }
  }
});

test('shade-first support saturation does not reward a larger exact-color rectangle', { skip: process.env.COLOR_EXPLORATION_DIRECT_TEST !== '1' }, async () => {
  const ids = ['precision-shade-001-a', 'precision-shade-001-b', 'precision-shade-001-c', 'precision-shade-001-d'];
  const result = await searchIndex(INDEX, buildDirectPaletteQuery({ method: 'palette-direct-precision', query: { swatchHex: '#ff2200' }, eligibleIds: ids, limit: 4 }));
  const scores = Object.fromEntries(result.hits.map(h => [h.id.at(-1), h.score]));
  assert.ok(Math.abs(scores.b - scores.d) < 0.03);
  assert.ok(scores.b > scores.a && scores.b > scores.c);
  assert.ok(scores.d > scores.a && scores.d > scores.c);
});

