        const c=chunk[index];
        if(skipping){
          if(skipping==='scalar'){
            if(!/[\s,}\]]/.test(c))continue;
            skipping=null;index--;continue;
          }
          if(skipQuoted){
            if(skipEscaped)skipEscaped=false;
            else if(c==='\\')skipEscaped=true;
            else if(c==='"'){skipQuoted=false;if(skipping==='string')skipping=null;}
