function profileCells(profile){return [`C${profile.concurrency}`,ms(profile.p95Ms),ms(profile.maxMs),String(profile.errors),String(profile.overOneSecond),ms(profile.warmupMaxMs),`${profile.warmupErrors??'?'} / ${profile.warmupOverOneSecond??'?'}`,profile.status.toUpperCase()];}
