  const millionRows=summary.methods.map(row=>'<tr><th scope="row">'+esc(row.label)+'</th><td>'+(row.million.length?row.million.map(profile=>'<div class="status '+profile.status+'"><strong>C'+profile.concurrency+' · '+esc(statusLabel(profile))+'</strong><br>'+esc(ms(profile.p95Ms)+' p95; '+ms(profile.maxMs)+' max; '+profile.errors+' errors; '+profile.overOneSecond+' timed ≥1s; '+(profile.warmupErrors??'?')+' warmup errors; '+(profile.warmupOverOneSecond??'?')+' warmup ≥1s')+'</div>').join(''):'<span class="pending">Not yet tested</span>')+'</td><td>'+esc(row.largestTestedCount?.toLocaleString('en-US')??'Not yet tested')+'</td></tr>').join('');
  const sensitivityRows=summary.sensitivities.map(r=>'<tr><th scope="row">'+esc(r.candidateId)+'</th><td><code>'+esc(JSON.stringify(r.configuration.parameters))+'</code></td><td>'+esc(r.coverage.ok+'/'+r.coverage.total)+'</td><td>'+pct(r.accuracy.queryMacroAgreement)+'</td><td>'+pct(r.withoutUncertain?.queryMacroAgreement)+'</td><td>'+ms(r.performance.p95Ms)+'</td><td><a href="'+esc(r.reportUrl)+'">'+esc(r.runLabel)+'</a></td></tr>').join('');
  const details=summary.methods.map(row=>{const r=row.record;return '<details id="'+esc(row.id)+'"><summary>'+esc(row.label)+'</summary>'+(r?'<p>Saved candidate <code>'+esc(r.candidateId)+'</code> in <a href="'+esc(r.reportUrl)+'">'+esc(r.runId)+'</a>.</p><p>Pair coverage: '+pct(r.accuracy.pairCoverage)+'; completely assessed cases: '+esc(r.accuracy.completeCases)+'; eligibility violations: '+esc(r.eligibilityViolations??0)+'.</p><ul>'+r.limitations.map(text=>'<li>'+esc(text)+'</li>').join('')+'</ul><h3>Recorded configuration and source evidence</h3><pre>'+esc(JSON.stringify({configuration:r.configuration,workload:r.workload,execution:r.execution,datasetHash:r.datasetHash,corpusHash:r.corpusHash,sourceHashes:r.sourceHashes,descriptorHashes:r.descriptorHashes},null,2))+'</pre>':'<p>No valid default feedback result.</p>')+(row.scaleProfiles.length?'<h3>Scale measurements</h3>'+table(['Documents','Concurrency','p95','Maximum','Errors','Timed ≥1s','Warmup maximum','Warmup errors / ≥1s','Strict result'],row.scaleProfiles.map(profile=>'<tr>'+[profile.count.toLocaleString('en-US'),...profileCells(profile)].map(value=>'<td>'+esc(value)+'</td>').join('')+'</tr>').join(''))+'<p>Artifacts:</p><ul>'+[...new Set(row.scaleProfiles.map(profile=>profile.artifact))].map(file=>'<li><code>'+esc(file)+'</code></li>').join('')+'</ul>':'<p>Scale measurements have not yet been saved for this method.</p>')+'</details>';}).join('');
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Color-query findings</title><style>body{font:16px/1.5 system-ui,sans-serif;background:#f5f7fa;color:#182234;margin:0}main{max-width:1600px;margin:auto;padding:28px}h1,h2,h3{line-height:1.2}h1{margin-bottom:8px}a{color:#164fb5}small{display:block;color:#5c6878}.lede{max-width:1000px}.cards{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0}.card{background:white;border:1px solid #dbe1ea;border-radius:10px;padding:15px 22px}.card strong{display:block;font-size:24px}.notice{background:#eef3ff;border-left:4px solid #315ab0;padding:12px 20px;margin:24px 0}.scroll{overflow:auto;border:1px solid #d7dfe8;border-radius:8px;margin:16px 0;background:white}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;border-bottom:1px solid #e0e6ed;padding:11px;vertical-align:top}thead th{background:#edf1f7;white-space:nowrap}tbody th{min-width:210px}td{min-width:85px}td:nth-child(6){min-width:170px}tbody tr:hover{background:#f7faff}.status{padding:8px;border-radius:6px;margin:4px 0}.pass{background:#eaf5ed}.fail{background:#fff0eb}.incomplete,.pending{color:#7a5800}.pending{background:#fff6d9;padding:4px 8px;border-radius:4px}details{background:white;border:1px solid #dbe1ea;border-radius:8px;padding:14px 18px;margin:12px 0}summary{cursor:pointer;font-weight:650}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f3f5f8;border-radius:5px;padding:15px;font-size:12px}code{font-size:12px;overflow-wrap:anywhere}.muted{color:#586476}nav{display:flex;gap:20px;flex-wrap:wrap;margin:20px 0}li{margin:6px 0}@media(max-width:600px){main{padding:16px}.card{padding:10px 14px}.notice{padding:10px 14px}table{font-size:13px}th,td{padding:9px}}</style></head><body><main><a href="/">← Visual prototypes</a><h1>Color-query findings</h1><p class="lede">Saved development accuracy and service performance, kept separate. No overall winner is declared. Refresh this page to include newly saved experiments.</p><p class="muted">Generated '+esc(summary.generatedAt)+'</p><div class="cards"><div class="card"><strong>'+summary.registryCount+'</strong>Registered methods</div><div class="card"><strong>'+summary.validDefaultMethods+'</strong>Valid default feedback results</div><div class="card"><strong>'+summary.corpus.count+'</strong>Corpus assets</div><div class="card"><strong>'+summary.caseCount+'</strong>Logical judgment cases</div></div><nav><a href="#accuracy">Accuracy and small-corpus speed</a><a href="#million">Million-document status</a><a href="#sensitivity">Parameter sensitivity</a><a href="#evidence">Evidence and limitations</a></nav><div class="notice"><strong>How to read these results</strong><ul>'+summary.caveats.map(text=>'<li>'+esc(text)+'</li>').join('')+'</ul></div><h2 id="accuracy">Development accuracy and small-corpus speed</h2><p>Each assessed query contributes equally to pairwise agreement. The same-case column compares all '+esc(summary.baseline?.supportedCases??20)+' HSV-supported cases; incomplete intersections are left unavailable. Unsupported cases and unjudged images are never assigned zero relevance.</p>'+table(headers,methodRows)+'<h2 id="million">Million-document status</h2><p>PASS requires every recorded warmup and timed request to finish below one second with no errors. Missing million-document results remain untested, even when a smaller corpus was fast. C1/C4/C16 indicate concurrent clients.</p>'+table(['Method','Million-document measurements','Largest corpus tested'],millionRows)+'<h2 id="sensitivity">Parameter sensitivity</h2><p>These '+summary.sensitivities.length+' configurations reuse the development judgments and remain separate from registered defaults. Differences are exploratory sensitivity, not held-out validation.</p><details><summary>Show parameter configurations</summary>'+table(['Candidate','Parameters','Supported','Agreement','Without uncertain pairs','p95','Report'],sensitivityRows)+'</details><h2 id="evidence">Evidence and limitations</h2>'+details+'<h3>Scale artifact provenance</h3><ul>'+summary.scaleRuns.map(run=>'<li><code>'+esc(run.filename)+'</code><br>'+esc(run.finishedAt?'Finished '+run.finishedAt:'In progress / no completion marker')+'; '+run.profilesRecorded+' saved profiles.<br>'+esc(run.provenanceLimitation)+'</li>').join('')+'</ul><details><summary>Excluded attempts ('+summary.excludedAttempts.length+')</summary><ul>'+summary.excludedAttempts.map(item=>'<li>'+esc(item.methodId)+' — <a href="'+esc(item.reportUrl)+'">'+esc(item.runId)+'</a>: '+esc(item.reason)+'</li>').join('')+'</ul></details>'+(summary.warnings.length?'<details open><summary>Artifact read warnings</summary><ul>'+summary.warnings.map(warning=>'<li>'+esc(warning)+'</li>').join('')+'</ul></details>':'')+'</main></body></html>';
}
function table(headers,rows){return '<div class="scroll"><table><thead><tr>'+headers.map(header=>'<th scope="col">'+esc(header)+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table></div>';}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
